import {londonEpoch} from './reminder-rules.mjs';
export function csvRows(text){const rows=[];let row=[],field='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){field+='"';i++;}else quoted=!quoted;}else if(!quoted&&(c===','||c==='\n')){row.push(field.replace(/\r$/,''));field='';if(c==='\n'){rows.push(row);row=[];}}else field+=c;}if(quoted)throw Error('Unclosed CSV quote');row.push(field.replace(/\r$/,''));rows.push(row);return rows.filter(r=>r.some(v=>v.trim()));}
export function importCSV(text,buildings){const rows=csvRows(text.replace(/^\uFEFF/,''));const header=(rows.shift()||[]).map(x=>x.trim().toLowerCase());const required=['title','date','start','end','building'];if(!required.every(k=>header.includes(k)))throw Error('CSV needs title,date,start,end,building,room');if(rows.length>500)throw Error('Maximum 500 rows');return rows.map((r,i)=>{const value=k=>(r[header.indexOf(k)]||'').trim();const c={title:value('title'),day:value('date'),time:value('start'),end:value('end'),building:value('building').toUpperCase(),room:value('room'),floor:value('floor'),notes:value('notes')};if(!c.title||c.title.length>200||!buildings.includes(c.building)||londonEpoch(c.day,c.time)===null||londonEpoch(c.day,c.end)===null||c.end<=c.time||c.room.length>50||c.notes.length>400)throw Error(`Invalid row ${i+2}: check date, time and building code`);return c;});}
export function dailyPlans(courses,profile,rainByDay={}){let lastDay='',previous=null;return [...courses].sort((a,b)=>(a.day+a.time).localeCompare(b.day+b.time)).map(c=>{const first=c.day!==lastDay;const rain=rainByDay[c.day]===true;const mode=first?(rain&&profile.mode==='walk'?'bus':profile.mode):'walk';const duration=first?Number(profile.minutes):Number(profile.campusMinutes||12);const buffer=Number(profile.buffer??10)+(rain?5:0);const start=londonEpoch(c.day,c.time);const depart=start-(duration+buffer)*60000;const conflict=!first&&previous?.end&&londonEpoch(previous.day,previous.end)>depart;const plan={...c,first,mode,duration,buffer,depart,rain,from:first?profile.origin:previous.building,conflict};lastDay=c.day;previous=c;return plan;});}
